                                                                PS2("ps2", "PlayStation 2", "PS2", "ps2", setOf("iso", "chd", "bin", "cso", "gz"), "xyz.aethersx2.android", "xyz.aethersx2.android.EmulationActivity", null, 0xFF1565C0),
