                                                                                enum class TopNavTab(val title: String) {
                                                                                    MY_GAMES("My Games"),
                                                                                        MEDIA("Media"),
                                                                                            SETTINGS("Settings")
                                                                                            }

                                                                                            // ============================================================================
                                                                                            // 2. Room Database Entity & DAO (ข้อมูลเกม, หน้าปก Custom Cover และสถิติ)
                                                                                            // ============================================================================
                                                                                            @Entity(
                                                                                                tableName = "games",
                                                                                                    indices = [Index(value = ["romFilePath"], unique = true), Index(value = ["consoleId"])]
                                                                                                    )
                                                                                                    data class GameItem(
                                                                                                        @PrimaryKey(autoGenerate = true) val id: Long = 0,
                                                                                                            val title: String,
                                                                                                                val consoleId: String,
                                                                                                                    val romFilePath: String,
                                                                                                                        val coverUrl: String? = null,
                                                                                                                            val customCoverUri: String? = null,
                                                                                                                                val fanartUrl: String? = null,
                                                                                                                                    val description: String = "กดปุ่ม [Options] เพื่อดึงข้อมูลหน้าปกและ Fanart จากฐานข้อมูลออนไลน์ (Scraper)",
                                                                                                                                        val releaseYear: String = "Unknown",
                                                                                                                                            val developer: String = "Retro Studio",
                                                                                                                                                val genre: String = "Action / Adventure",
                                                                                                                                                    val timePlayedMinutes: Int = 0,
                                                                                                                                                        val progressPercent: Int = 0,
                                                                                                                                                            val trophiesEarned: Int = 0,
                                                                                                                                                                val trophiesTotal: Int = 0,
                                                                                                                                                                    val lastPlayedTimestamp: Long? = null,
                                                                                                                                                                        val isFavorite: Boolean = false
                                                                                                                                                                        ) {
                                                                                                                                                                            val effectiveCoverModel: String?
                                                                                                                                                                                    get() = customCoverUri?.takeIf { it.isNotBlank() } ?: coverUrl

                                                                                                                                                                                        val formattedPlayTime: String
                                                                                                                                                                                                get() {
                                                                                                                                                                                                            val hours = timePlayedMinutes / 60
                                                                                                                                                                                                                        val mins = timePlayedMinutes % 60
                                                                                                                                                                                                                                    return if (hours > 0) "${hours}h ${mins}m" else "${mins}m"
                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                            @Dao
                                                                                                                                                                                                                                            interface GameDao {
                                                                                                                                                                                                                                                @Query("SELECT * FROM games WHERE consoleId = :consoleId ORDER BY isFavorite DESC, title ASC")
                                                                                                                                                                                                                                                    fun observeGamesByConsole(consoleId: String): Flow<List<GameItem>>

                                                                                                                                                                                                                                                        @Query("SELECT * FROM games WHERE title LIKE '%' || :query || '%' ORDER BY title ASC")
                                                                                                                                                                                                                                                            fun searchGames(query: String): Flow<List<GameItem>>

                                                                                                                                                                                                                                                                @Insert(onConflict = OnConflictStrategy.IGNORE)
                                                                                                                                                                                                                                                                    suspend fun insertGames(games: List<GameItem>)

                                                                                                                                                                                                                                                                        @Update
                                                                                                                                                                                                                                                                            suspend fun updateGame(game: GameItem)

                                                                                                                                                                                                                                                                                @Query("UPDATE games SET customCoverUri = :customUri WHERE id = :gameId")
                                                                                                                                                                                                                                                                                    suspend fun updateCustomCover(gameId: Long, customUri: String?)
                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                    @Database(entities = [GameItem::class], version = 1, exportSchema = false)
                                                                                                                                                                                                                                                                                    abstract class LauncherDatabase : RoomDatabase() {
                                                                                                                                                                                                                                                                                        abstract fun gameDao(): GameDao
                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                        // ============================================================================
                                                                                                                                                                                                                                                                                        // 3. ระบบสแกนโฟลเดอร์ ROMs และระบบ Scraper ดึงข้อมูลปก/Fanart ออนไลน์
                                                                                                                                                                                                                                                                                        // ============================================================================
                                                                                                                                                                                                                                                                                        class RomScannerManager {
                                                                                                                                                                                                                                                                                            private val regionTagRegex = Regex("""\s*(\([^)]*\)|\[[^\]]*\])""")

                                                                                                                                                                                                                                                                                                suspend fun scanDirectoryForRoms(rootDirectory: File): List<GameItem> = withContext(Dispatchers.IO) {
                                                                                                                                                                                                                                                                                                        if (!rootDirectory.exists() || !rootDirectory.isDirectory) return@withContext emptyList()
                                                                                                                                                                                                                                                                                                                val discovered = mutableListOf<GameItem>()
                                                                                                                                                                                                                                                                                                                        ConsolePlatform.entries.forEach { platform ->
                                                                                                                                                                                                                                                                                                                                    val folder = File(rootDirectory, platform.folderName)
                                                                                                                                                                                                                                                                                                                                                if (folder.exists() && folder.isDirectory) {
                                                                                                                                                                                                                                                                                                                                                                folder.walkTopDown().maxDepth(3)
                                                                                                                                                                                                                                                                                                                                                                                    .filter { it.isFile && it.extension.lowercase(Locale.ROOT) in platform.supportedExtensions }
                                                                                                                                                                                                                                                                                                                                                                                                        .forEach { romFile ->
                                                                                                                                                                                                                                                                                                                                                                                                                                val cleanTitle = romFile.nameWithoutExtension.replace(regionTagRegex, "").replace("_", " ").trim().ifEmpty { romFile.nameWithoutExtension }
                                                                                                                                                                                                                                                                                                                                                                                                                                                        discovered.add(GameItem(title = cleanTitle, consoleId = platform.id, romFilePath = romFile.absolutePath, trophiesTotal = 30))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        discovered
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            data class ScrapedGameMetadataDto(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                val cleanTitle: String,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    val boxartCoverUrl: String,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        val fanartBackgroundUrl: String,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            val overviewDescription: String,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                val releaseYear: String,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    val developerName: String,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        val genreName: String
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        )

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        interface MetadataScraperApi {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            @GET("v1/games/search")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                suspend fun searchGameMetadata(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        @Query("query") titleQuery: String,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                @Query("platform") platformId: String,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        @Query("api_key") apiKey: String
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ): List<ScrapedGameMetadataDto>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            class MetadataScraperService(private val api: MetadataScraperApi? = null) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                suspend fun scrapeGameMetadata(game: GameItem): ScrapedGameMetadataDto = withContext(Dispatchers.IO) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    val remote = api?.searchGameMetadata(game.title, game.consoleId, "YOUR_SCRAPER_API_KEY")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!remote.isNullOrEmpty()) return@withContext remote.first()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } catch (_: Exception) {}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                delay(400)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ScrapedGameMetadataDto(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    cleanTitle = game.title,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                boxartCoverUrl = "https://picsum.photos/seed/${game.title.hashCode()}_cover/600/850",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            fanartBackgroundUrl = "https://picsum.photos/seed/${game.title.hashCode()}_fanart/1920/1080",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        overviewDescription = "${game.title} บนเครื่อง ${game.consoleId.uppercase()} ดึงข้อมูลหน้าปกและภาพพื้นหลัง Fanart ความละเอียดสูงจาก Online Scraper เรียบร้อยแล้ว",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    releaseYear = game.releaseYear.takeIf { it != "Unknown" } ?: "2004",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                developerName = game.developer,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            genreName = game.genre
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // ============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // 4. กลไกการเปิดเกมผ่าน Android Intent พร้อมส่ง File Path ของ ROM
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // ============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        class EmulatorIntentLauncher(private val context: Context) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            sealed class LaunchResult {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    data object Success : LaunchResult()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            data class EmulatorNotInstalled(val packageName: String, val platformName: String) : LaunchResult()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    data class Error(val message: String) : LaunchResult()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            fun launchGame(game: GameItem, platform: ConsolePlatform): LaunchResult {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    val romFile = File(game.romFilePath)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            val contentUri: Uri = try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (romFile.exists()) FileProvider.getUriForFile(context, "${context.packageName}.fileprovider", romFile)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    else Uri.fromFile(romFile)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } catch (_: Exception) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Uri.fromFile(romFile)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!isPackageInstalled(platform.defaultEmulatorPackage)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return LaunchResult.EmulatorNotInstalled(platform.defaultEmulatorPackage, platform.displayName)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    val intent = Intent(Intent.ACTION_VIEW).apply {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                setPackage(platform.defaultEmulatorPackage)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            platform.defaultEmulatorActivity?.let { component = ComponentName(platform.defaultEmulatorPackage, it) }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP or Intent.FLAG_GRANT_READ_URI_PERMISSION)

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    when (platform) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ConsolePlatform.PSP -> {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        setDataAndType(contentUri, "application/octet-stream")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            putExtra("org.ppsspp.ppsspp.Shortcuts", romFile.absolutePath)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ConsolePlatform.GAMECUBE, ConsolePlatform.WII -> {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                setDataAndType(contentUri, "application/octet-stream")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    putExtra("AutoStartFile", romFile.absolutePath)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ConsolePlatform.PS1, ConsolePlatform.PS2 -> {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        setDataAndType(contentUri, "application/octet-stream")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            putExtra("bootPath", romFile.absolutePath)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ConsolePlatform.NDS -> {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                setDataAndType(contentUri, "application/octet-stream")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    putExtra("GAMEPATH", romFile.absolutePath)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ConsolePlatform.N3DS, ConsolePlatform.SWITCH -> {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        setDataAndType(contentUri, "application/octet-stream")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            putExtra("GamePath", romFile.absolutePath)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ConsolePlatform.NES, ConsolePlatform.SNES, ConsolePlatform.GBA -> {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (platform.defaultEmulatorPackage.contains("retroarch")) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        action = Intent.ACTION_MAIN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                addCategory(Intent.CATEGORY_LAUNCHER)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        putExtra("ROM", romFile.absolutePath)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                putExtra("LIBRETRO", "/data/data/${platform.defaultEmulatorPackage}/cores/${platform.retroArchCoreName}")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            setDataAndType(contentUri, "application/octet-stream")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        context.startActivity(intent)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    LaunchResult.Success
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } catch (e: Exception) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        LaunchResult.Error(e.localizedMessage ?: "ไม่สามารถเปิดเกมได้")
